/**
 * D4 — Assert the generated deploy artifact equals the canonical source.
 *
 * `xpizza-functions/database.rules.json` is gitignored and generated by `npm run sync:rules`
 * from the canonical `xpizza-reference/database.rules.json`. This guards against deploying a
 * stale or hand-edited artifact: run after sync, it byte-compares the two. Wired into
 * `npm run check:rules` (and therefore the database predeploy hook).
 */
const fs = require('fs');
const path = require('path');
const assert = require('assert');

const generated = path.join(__dirname, '..', 'database.rules.json');
const canonical = path.join(__dirname, '..', '..', 'xpizza-reference', 'database.rules.json');

const gen = fs.readFileSync(generated);
const can = fs.readFileSync(canonical);

assert(
  gen.equals(can),
  'FAIL: generated xpizza-functions/database.rules.json differs from canonical ' +
    'xpizza-reference/database.rules.json — run `npm run sync:rules`'
);

console.log('assert-rules-synced: OK (deploy artifact == canonical)');
